// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.fragment;

import org.eclipse.rdf4j.sail.lmdb.ValueIds;

/**
 * Access-restriction fragments (fragment-fusion M4): instead of evaluating a predicate over every visited id, these
 * change <em>what gets traversed</em> — a range predicate becomes two seeks over an ordered run, an EXISTS becomes a
 * probe that stops at the first witness, a selective side becomes a sorted SIP domain constraining the other side. A
 * predicate that becomes a run bound changes the number of ids visited, which no per-row speedup can match.
 *
 * <p>
 * The engine adapters implement {@link OrderedRunView}/{@link AdjacencyView} over the real run/adjacency machinery (for
 * example {@code RunView.lowerBound} and {@code NativeAdjacency.find}); the fragment side stays free of deep engine
 * types so every mechanism here is testable standalone.
 */
public final class FragmentAccess {

	private FragmentAccess() {
	}

	/** A run of ids in unsigned nondecreasing order that may support seeking. */
	public interface OrderedRunView {
		long size();

		long idAt(long index);

		/**
		 * First index in {@code [from, size())} whose id is unsigned-≥ {@code key}, or {@code -1} when this run cannot
		 * seek (the caller falls back to the predicate variant).
		 */
		long seekFirstAtLeast(long from, long key);
	}

	/** A minimal adjacency surface for probe fragments: neighbor runs by key. */
	public interface AdjacencyView {
		/** Run handle for the key, or {@code <= 0} when the key has no neighbors. */
		long find(long key);

		long size(long runHandle);

		long neighborAt(long runHandle, long index);
	}

	/** Packs a half-open index window {@code [start, end)}; {@link #NO_WINDOW} means the restriction does not apply. */
	public static final long NO_WINDOW = -1L;

	public static long window(long start, long endExclusive) {
		return start << 32 | (endExclusive & 0xffff_ffffL);
	}

	public static int windowStart(long window) {
		return (int) (window >>> 32);
	}

	public static int windowEnd(long window) {
		return (int) window;
	}

	/**
	 * Compiles {@code lo <= id < hi} (unsigned id-space bounds, as produced for value-ordered inline integer ranges
	 * whose index keys are order-preserving) into a run window via two seeks. Returns {@link #NO_WINDOW} when the run
	 * cannot seek; the caller keeps the predicate/slice variant. An empty restriction returns a zero-length window.
	 */
	public static long restrictToRange(OrderedRunView run, long loInclusive, long hiExclusive) {
		long start = run.seekFirstAtLeast(0, loInclusive);
		if (start < 0) {
			return NO_WINDOW;
		}
		long end = run.seekFirstAtLeast(start, hiExclusive);
		if (end < 0) {
			return NO_WINDOW;
		}
		return window(start, end);
	}

	/**
	 * The id-space window of all value-ordered inline integer ids of one type code whose numeric value lies in
	 * {@code [loValue, hiValue)}: because the ordered encoding is order-preserving in the id's value field, the window
	 * is contiguous per type code. Returns {@code [loId, hiId)} packed as two ids via the caller-provided array.
	 */
	public static void orderedIntegerIdRange(int typeCode, long loValue, long hiValue, long[] loHiOut) {
		loHiOut[0] = ValueIds.createId(typeCode, loValue + ValueIds.ORDERED_BIAS);
		loHiOut[1] = ValueIds.createId(typeCode, hiValue + ValueIds.ORDERED_BIAS);
	}

	/** What a probe consumer needs — bare existence, its negation, or the first witness id. */
	public enum ProbeMode {
		EXISTS,
		NOT_EXISTS,
		FIRST_WITNESS
	}

	/**
	 * The probe family (EXISTS / NOT EXISTS / semi-join / witness): walks one key's neighbor run through an optional
	 * inner predicate fragment, stopping at the first witness. Returns, per mode: 1/0 for (NOT_)EXISTS, the witness id
	 * or {@code -1} for FIRST_WITNESS.
	 */
	public static long probe(AdjacencyView adjacency, long key, ProbeMode mode, LongPredicateFragment inner,
			FragmentBinding innerBinding) {
		long run = adjacency.find(key);
		long witness = -1L;
		if (run > 0L) {
			long size = adjacency.size(run);
			for (long i = 0; i < size; i++) {
				long neighbor = adjacency.neighborAt(run, i);
				if (inner == null || inner.testAtFilterSite(neighbor, -1L, -1L, innerBinding)) {
					witness = neighbor;
					break;
				}
			}
		}
		switch (mode) {
		case EXISTS:
			return witness != -1L ? 1L : 0L;
		case NOT_EXISTS:
			return witness != -1L ? 0L : 1L;
		default:
			return witness;
		}
	}

	/**
	 * Builds a sorted, deduplicated SIP domain from the keys accepted by a probe or scan — the reusable form of "the
	 * selective inner side constrains the outer traversal". Input need not be sorted.
	 */
	public static long[] buildSipDomain(long[] acceptedKeys, int count) {
		long[] domain = new long[count];
		System.arraycopy(acceptedKeys, 0, domain, 0, count);
		java.util.Arrays.sort(domain);
		int out = 0;
		for (int i = 0; i < count; i++) {
			if (out == 0 || domain[out - 1] != domain[i]) {
				domain[out++] = domain[i];
			}
		}
		return out == count ? domain : java.util.Arrays.copyOf(domain, out);
	}

	/** Intersects two sorted domains (signed order, matching {@link #buildSipDomain}). */
	public static long[] intersectSipDomains(long[] left, long[] right) {
		long[] intersection = new long[Math.min(left.length, right.length)];
		int l = 0;
		int r = 0;
		int out = 0;
		while (l < left.length && r < right.length) {
			if (left[l] < right[r]) {
				l++;
			} else if (left[l] > right[r]) {
				r++;
			} else {
				intersection[out++] = left[l];
				l++;
				r++;
			}
		}
		return out == intersection.length ? intersection : java.util.Arrays.copyOf(intersection, out);
	}
}
